CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (auth.role()='service_role' OR auth.uid() IS NULL OR (_user_id=auth.uid() AND public.is_mfa_session_verified())) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE OR REPLACE FUNCTION public.is_admin_or_editor(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'super_admin') OR public.has_role(_user_id,'admin') OR public.has_role(_user_id,'editor') $$;
CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid,_content_type text,_action text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'super_admin') OR ((auth.role()='service_role' OR auth.uid() IS NULL OR (_user_id=auth.uid() AND public.is_mfa_session_verified())) AND EXISTS(SELECT 1 FROM public.user_roles ur JOIN public.role_permissions rp ON ur.role=rp.role WHERE ur.user_id=_user_id AND rp.content_type=_content_type AND ((_action='create' AND rp.can_create) OR (_action='edit' AND rp.can_edit) OR (_action='delete' AND rp.can_delete) OR (_action='publish' AND rp.can_publish)))) $$;
CREATE OR REPLACE FUNCTION public.is_assigned_to_country(_user_id uuid,_country_code text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (auth.role()='service_role' OR auth.uid() IS NULL OR (_user_id=auth.uid() AND public.is_mfa_session_verified())) AND EXISTS(SELECT 1 FROM public.user_country_assignments WHERE user_id=_user_id AND country_code=_country_code) $$;